func main() {
	// Simulate game sessions
	gameSessions := []GameSession{
		{UserID: 1, GameID: 1, StartTime: time.Now(), EndTime: time.Now().Add(time.Minute * 10)},
		{UserID: 1, GameID: 2, StartTime: time.Now().Add(time.Minute * 15), EndTime: time.Now().Add(time.Minute * 30)},
