		{UserID: 3, GameID: 1, StartTime: time.Now().Add(time.Minute * 40), EndTime: time.Now().Add(time.Minute * 50)},
	}
	// Calculate total game time per user
	totalGameTime := make(map[int]time.Duration)
	for _, session := range gameSessions {
		totalGameTime[session.UserID] += session.Duration
	}
	// Print total game time per user
	fmt.Println("Total game time per user:")
	for userID, duration := range totalGameTime {
		fmt.Printf("User %d: %v\n", userID, duration)
	}
	// Calculate average game time per session
	var totalDuration time.Duration
	for _, session := range gameSessions {
		totalDuration += session.Duration
	}
	averageDuration := totalDuration / time.Duration(len(gameSessions))
	// Print average game time per session
	fmt.Printf("Average game time per session: %v\n", averageDuration)
	// Identify potential issues
	for _, session := range gameSessions {
		if session.Duration > time.Hour {
