How can I retrieve the population of Thailand in 2019 using Java code?
Here's a possible solution using the World Bank API:
String countryCode = "THA";
String indicatorCode = "SP.POP.TOTL";
int year = 2019;
String apiUrl = String.format("http://api.worldbank.org/v2/country/%s/indicator/%s?date=%d&format=json", countryCode, indicatorCode, year);
try {
    URL url = new URL(apiUrl);
    HttpURLConnection conn = (HttpURLConnection) url.openConnection();
    conn.setRequestMethod("GET");
    BufferedReader reader = new BufferedReader(new InputStreamReader(conn.getInputStream()));
    StringBuilder response = new StringBuilder();
    String line;
    while ((line = reader.readLine()) != null) {
        response.append(line);
    }
    reader.close();
    JSONArray jsonArray = new JSONArray(response.toString());
    JSONArray data = jsonArray.getJSONArray(1);
    JSONObject latest = data.getJSONObject(data.length() - 1);
    String population = latest.getString("value");
    System.out.println("The population of Thailand in 2019 was " + population);
} catch (IOException | JSONException e) {
    e.printStackTrace();
}

