        return
    }

    let calendar = Calendar.current
    let now = Date()
    let startOfDay = calendar.startOfDay(for: now)
    let predicate = HKQuery.predicateForSamples(withStart: startOfDay, end: now, options: .strictStartDate)
    let query = HKStatisticsQuery(quantityType: waterType, quantitySamplePredicate: predicate, options: .cumulativeSum) { (query, result, error) in
        guard let result = result, let sum = result.sumQuantity() else {
            print("Error retrieving water intake: \(error?.localizedDescription ?? "Unknown error")")
            return
        }

        let water = sum.doubleValue(for: HKUnit.fluidOunceUS())
        print("Water intake today: \(water) fl oz")
    }

    healthStore.execute(query)
}
Lastly, here's an example of how to retrieve sleep duration data using the HealthKit framework:
let healthStore = HKHealthStore()
let sleepType = HKCategoryType.categoryType(forIdentifier: .sleepAnalysis)!
healthStore.requestAuthorization(toShare: [], read: [sleepType]) { (success, error) in
    if let error = error {
        print("Error requesting authorization: \(error.localizedDescription)")
        return
    }

    let calendar = Calendar.current
    let now = Date()
    let startOfDay = calendar.startOfDay(for: now)
    let predicate = HKQuery.predicateForSamples(withStart: startOfDay, end: now, options: .strictStartDate)
    let query = HKSampleQuery(sampleType: sleepType, predicate: predicate, limit: HKObjectQueryNoLimit, sortDescriptors: nil) { (query, samples, error) in
        guard let samples = samples as? [HKCategorySample] else {
            print("Error retrieving sleep duration: \(error?.localizedDescription ?? "Unknown error")")
            return
        }

        let sleepDuration = samples.reduce(0) { (result, sample) -> TimeInterval in
            let duration = sample.endDate.timeIntervalSince(sample.startDate)
            return result + duration
        }

        print("Sleep duration last night: \(sleepDuration / 3600) hours")
    }

    healthStore.execute(query)
}

