  },
  {
    name: 'Query Processing',
    description: 'Confirm that the correct query is being processed'
  }
]
def get_component(name)
  @components.find { |c| c[:name] == name }
end
def get_dependencies(name)
  get_component(name)[:dependencies]
end
def get_response_time(name)
  get_component(name)[:response_time]
end
def get_checkpoint(name)
  @checkpoints.find { |c| c[:name] == name }
end
def generate_sequence_diagram
  diagram = []
  current_time = 0
  # Add User Input component
  diagram << "User Input ->"
  # Add Intent Recognition component
  current_time += get_response_time('User Input')
  diagram << "Intent Recognition: #{current_time}s ->"
  get_dependencies('Intent Recognition').each do |dep|
    if dep[:type] == 'input'
      current_time += get_response_time(dep[:component])
      diagram << "#{dep[:component]}: #{current_time}s ->"
    end
  end
  # Add Query Processing component
  checkpoint = get_checkpoint('Intent Recognition')
  current_time += get_response_time('Intent Recognition')
  diagram << "Query Processing: #{current_time}s -> #{checkpoint[:name]}: #{current_time}s ->"
  get_dependencies('Query Processing').each do |dep|
    if dep[:type] == 'input'
      current_time += get_response_time(dep[:component])
      diagram << "#{dep[:component]}: #{current_time}s ->"
    end
  end
  # Add Response Generation component
  checkpoint = get_checkpoint('Query Processing')
  current_time += get_response_time('Query Processing')
  diagram << "Response Generation: #{current_time}s -> #{checkpoint[:name]}: #{current_time}s"
  # Print the sequence diagram
  puts diagram.join(' ')
end
